import{_ as a,c as e,o as t,ah as s}from"./chunks/framework.Dnh4IO1K.js";const h=JSON.parse('{"title":"否","description":"东坡易传 - 否","frontmatter":{"title":"否","description":"东坡易传 - 否"},"headers":[],"relativePath":"zh/classics/dongpo/013.md","filePath":"zh/classics/dongpo/013.md"}'),o={name:"zh/classics/dongpo/013.md"};function r(n,p,c,_,i,d){return t(),e("div",null,[...p[0]||(p[0]=[s('<h1 id="否" tabindex="-1">否 <a class="header-anchor" href="#否" aria-label="Permalink to “否”">​</a></h1><p>否：“否”之匪人，不利君子貞；大往小來。</p><p>《彖》曰：“‘否’之匪人，不利君子貞；大往小來”，則是天地不交而萬物不通也，上下不交而天下無邦也。內陰而外陽，內柔而外剛，內小人而外君子，小人道長，君子道消也。</p><p>《春秋傳》曰：“不有君子，其能國乎？”君子道消，雖有國，與無同矣。</p><p>象曰：天地不交，“否”；君子以儉德闢難，不可榮以祿。</p><p>初六：拔茅茹，以其匯，貞吉，亨。象曰：“拔茅”“貞吉”，志在君也。</p><p>自“泰”爲“否”也易，自“否”爲“泰”也難。何也？陰陽易位，未有不志於復，而其既復，未有不安其位者也。故“泰”有“徵”，而“否”無“徵”。夫苟無“徵”，則是終無“泰”也而可乎？故“坤”處內而不忘貞於“乾”，斯所以爲“泰”之漸矣，故“亨”。</p><p>六二：包承，小人吉，大人否，亨。象曰：“大人否，亨”，不亂羣也。</p><p>陰得其位，欲包羣陽，而以承順取之。上說其順而不知其害，此小人之吉也。大人之慾濟斯世也，苟出而爭之，上則君莫之信，下則小人之所疾，故莫如否。大人否而退，使君子小人之羣不相亂，以爲邪之勝正也，常於交錯未定之間，及其羣分類別，正未有不勝者也，故“亨”。</p><p>六三：包羞。象曰：“包羞”，位不當也。</p><p>三本陽位，故包承羣陽而知羞之矣。</p><p>九四：有命，無咎；疇離祉。象曰：“有命無咎”，志行也。</p><p>君子之居“否”，患無以自行其志爾①。初六有志於君，而四之應；苟“有命”，我無庸咎之矣。故君子之疇獲離其福。“疇”，類也。</p><p>【校注】 ① 患無以自行其志爾：《蘇氏易傳》無“以”字。</p><p>九五：休否，大人吉；其亡其亡，繫於苞桑。象曰：“大人”之“吉”，位正當也。</p><p>九五，大人之得位，宜若甚安且強者也。然其實制在於內。席其安強之勢，以與小人爭而求勝，則不可。故曰“休否，大人吉”。恃其安強之勢，而不虞小人之內勝，亦不可。故曰“其亡其亡，繫於苞桑”。“休否”者，所謂“大人否”也，小人之不吾敵也，審矣。惟乘吾急，則有以幸勝之，利在於急，不在於緩也。苟否而不爭，以休息之，必有不吾敵者見焉，故“大人吉”。</p><p>上九：傾否，先否後喜。象曰：否終則傾，何可長也。</p><p>“否”至於此，不可復因。非傾蕩掃除，則喜無自至矣。</p>',18)])])}const m=a(o,[["render",r]]);export{h as __pageData,m as default};
